import { roundCents } from './money.js';
import { isValidDate, calculateDueDate } from './dates.js';

/**
 * Check if a discount percent is valid: a number from 0 to 100.
 * @param {unknown} discount
 * @returns {boolean}
 */
function isValidDiscountPercent(discount) {
  return typeof discount === 'number' && discount >= 0 && discount <= 100;
}

/**
 * Create an invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }} params
 * @returns {{ ok: true, value: { customerId: string, customerName: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent: number }>, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize and validate customer ID
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;

  // Validate date format
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate and calculate due date based on terms
  const dueDate = calculateDueDate(issueDate, terms);
  if (dueDate === null) return fail('TERMS_INVALID');

  // Validate lines array
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Build invoice lines
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Determine discount: use line's discount if provided, otherwise use customer tier discount
    const discountPercent =
      line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customer.tier];
    if (!isValidDiscountPercent(discountPercent)) return fail('DISCOUNT_INVALID');

    // Get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    customerName: customer.name,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
    terms,
    dueDate,
  });
}

/**
 * Calculate the total for a single line: qty × unitPrice (in cents).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate subtotal and total for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  let discount = 0;
  let vat = 0;

  for (const line of invoice.lines) {
    const lineAmount = lineTotal(line);
    subtotal += lineAmount;
    const lineDiscount = roundCents(lineAmount * (line.discountPercent ?? 0) / 100);
    discount += lineDiscount;
    const lineVat = roundCents((lineAmount - lineDiscount) * (line.vatRate / 100));
    vat += lineVat;
  }

  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return { subtotal, discount, vat, voucher, total };
}

/**
 * Add or update a line on a draft invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} params
 * @returns {{ ok: true, value: typeof invoice } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate discountPercent if provided
  const discount = discountPercent ?? 0;
  if (!isValidDiscountPercent(discount)) return fail('DISCOUNT_INVALID');

  // Get product
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLine = { sku, name: product.name, qty, unitPrice: product.unitPrice, vatRate: product.vatRate, discountPercent: discount };

  // Check if line with this SKU already exists
  const existingLineIndex = invoice.lines.findIndex((l) => l.sku === sku);

  let newLines;
  if (existingLineIndex >= 0) {
    // Update existing line's qty and discount
    newLines = invoice.lines.map((line, i) =>
      i === existingLineIndex ? { ...line, qty: line.qty + qty, discountPercent: discount } : line,
    );
  } else {
    // Add new line
    newLines = [...invoice.lines, newLine];
  }

  return ok({
    customerId: invoice.customerId,
    customerName: invoice.customerName,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
    terms: invoice.terms,
    dueDate: invoice.dueDate,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: typeof invoice } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Find line with this SKU
  const lineIndex = invoice.lines.findIndex((l) => l.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  // Check if removing it would leave no lines
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Create new lines array without this line
  const newLines = invoice.lines.filter((line, i) => i !== lineIndex);

  return ok({
    customerId: invoice.customerId,
    customerName: invoice.customerName,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
    terms: invoice.terms,
    dueDate: invoice.dueDate,
  });
}

/**
 * Issue a draft invoice, assigning it a number and marking it as issued.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }} invoice
 * @param {string[]} existingNumbers
 * @returns {{ ok: true, value: typeof invoice & { number: string } } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Get next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    customerId: invoice.customerId,
    customerName: invoice.customerName,
    issueDate: invoice.issueDate,
    number,
    status: 'issued',
    lines: invoice.lines,
    terms: invoice.terms,
    dueDate: invoice.dueDate,
  });
}

/**
 * Apply a voucher to a draft invoice, reducing the total after VAT.
 * @param {{ customerId: string, customerName: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string, voucher?: { code: string, amount: number } }} invoice
 * @param {{ code: string, amount: number }} params
 * @returns {{ ok: true, value: typeof invoice } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check no existing voucher
  if (invoice.voucher) return fail('VOUCHER_EXISTS');

  // Validate amount
  if (!Number.isInteger(amount) || amount <= 0) return fail('AMOUNT_INVALID');

  // Create new invoice with voucher
  return ok({
    customerId: invoice.customerId,
    customerName: invoice.customerName,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: invoice.lines,
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    voucher: { code, amount },
  });
}

